steps.command:
python3 - <<'EOF'
p='billing/refunds.py'
s=open(p).read()
a=s.index("def refund_invoice")
b=s.index("def credit_invoice")
new='''def _refundable(payment: Payment) -> Cents:
    if payment["gateway_ref"] is None:
        return Cents(0)
    return Cents(max(payment["amount"] - payment["refunded_amount"], 0))


def _credit_returned(ctx: Context, invoice: Invoice) -> bool:
    return any(
        entry["reason"] == "refund" and entry["invoice_id"] == invoice["id"]
        for entry in ctx.store.ledger_for(invoice["customer_id"])
    )


def refund_invoice(
    ctx: Context, invoice_id: InvoiceId, reason: str = "requested_by_customer", amount: Cents | None = None
) -> CreditNote:
    """Refund paid money back to the original payment method, oldest payments first.

    Without an amount, everything still refundable is refunded and any applied account credit is returned.
    """
    invoice = ctx.store.require_invoice(invoice_id)
    if invoice["status"] != "paid":
        raise InvalidStateError("only paid invoices can be refunded")
    if any(not note["refunded"] for note in ctx.store.credit_notes_for(invoice_id)):
        raise InvalidStateError("invoice has already been credited")
    payments = sorted(successful_payments(ctx, invoice["id"]), key=lambda p: (p["created_at"], p["id"]))
    refundable = Cents(sum(_refundable(payment) for payment in payments))
    return_credit = amount is None and invoice["credit_applied"] > 0 and not _credit_returned(ctx, invoice)
    if amount is None:
        if refundable == 0 and not return_credit:
            raise InvalidStateError("invoice has nothing left to refund")
        to_refund = refundable
    else:
        if amount <= 0:
            raise ValidationError("refund amount must be positive")
        if refundable == 0:
            raise InvalidStateError("invoice has nothing left to refund")
        if amount > refundable:
            raise ValidationError(f"cannot refund more than {refundable} on this invoice")
        to_refund = amount
    left = to_refund
    for payment in payments:
        if left <= 0:
            break
        take = Cents(min(_refundable(payment), left))
        if take <= 0:
            continue
        assert payment["gateway_ref"] is not None
        result = ctx.gateway.refund(payment["gateway_ref"], take)
        if not result["ok"]:
            raise InvalidStateError(f"gateway refused refund for payment {payment['id']}")
        payment["refunded_amount"] = Cents(payment["refunded_amount"] + take)
        payment["status"] = "refunded" if payment["refunded_amount"] >= payment["amount"] else "partially_refunded"
        left = Cents(left - take)
        emit(ctx, "payment.refunded", {"payment": payment_json(payment)})
    credit = invoice["credit_applied"] if return_credit else Cents(0)
    if credit > 0:
        add_entry(ctx, invoice["customer_id"], credit, "refund", invoice["id"])
    return _credit_note(ctx, invoice_id, Cents(to_refund + credit), reason, True)


'''
s=s[:a]+new+s[b:]
s=s.replace("from .models import Cents, CreditNote, InvoiceId","from .models import Cents, CreditNote, Invoice, InvoiceId, Payment")
open(p,'w').write(s)

p='billing/engine.py'
s=open(p).read()
s=s.replace('''    def refund(self, invoice_id: InvoiceId, reason: str = "requested_by_customer") -> CreditNote:
        return refunds.refund_invoice(self.ctx, invoice_id, reason)''','''    def refund(
        self, invoice_id: InvoiceId, reason: str = "requested_by_customer", amount: Cents | None = None
    ) -> CreditNote:
        return refunds.refund_invoice(self.ctx, invoice_id, reason, amount)''')
open(p,'w').write(s)

p='billing/api.py'
s=open(p).read()
s=s.replace('''    note = engine.refund(InvoiceId(params[0]), _optional_str(body, "reason") or "requested_by_customer")''','''    amount = Cents(_int(body, "amount")) if body.get("amount") is not None else None
    note = engine.refund(InvoiceId(params[0]), _optional_str(body, "reason") or "requested_by_customer", amount)''')
open(p,'w').write(s)
EOF
grep -n "^from .models\|Cents" billing/engine.py billing/api.py | head; echo '{"summary": "Added optional partial refund amounts to refund_invoice, BillingEngine.refund and the refund API, spreading refunds over payments oldest first with partially_refunded status."}' > answer.json
.venv/bin/python -m pytest -q 2>&1 | tail -3; .venv/bin/python -m mypy billing | tail -5
